# Generated by manage.py generate_test_cases.
"""Discover incoming registrations through IM provider definitions."""

import json

from django.http import HttpResponse

from bloomerp.tests.base import (
    BloomerpComponentTestCase,
    ExpectedResult,
    RequestScenario,
)
from bloomerp.tests.components.communication.voip.fixtures import ComponentFixtures


class TestCallRegistrationsComponent(ComponentFixtures, BloomerpComponentTestCase):
    view_name = "components_im_call_registrations"

    def registrations(self, response: HttpResponse) -> bool:
        """Expose only the assigned account and its provider-selected registration driver."""
        entries = json.loads(response.content)["registrations"]
        return (
            len(entries) == 1
            and entries[0]["id"] == str(self.connection.pk)
            and entries[0]["driver"] == "voip"
        )

    def get_test_scenarios(self) -> list[RequestScenario]:
        """Verify registration discovery is authenticated and line-scoped."""
        return [
            RequestScenario(
                name="Assigned accounts",
                user=self.normal_user,
                prepare=self.prepare_request,
                expected=ExpectedResult(response_validators=self.registrations),
            ),
            RequestScenario(
                name="Revoked account absent",
                user=self.normal_user,
                prepare=self.revoke_line,
                expected=ExpectedResult(
                    response_validators=self.json_key_equals("registrations", [])
                ),
            ),
            RequestScenario(
                name="Login required",
                prepare=self.prepare_request,
                expected=ExpectedResult(status_code=302),
            ),
        ]
